import { frontmatter } from "./frontmatter";
import { escapeCell, region } from "./markdown";
import type { IndexRow } from "./models/IndexRow";
import { pbiNoteName, sprintNoteName } from "./paths";

export function renderBacklogIndex(rows: IndexRow[], sprintPaths: string[], notesSection: string): string {
  const inScope = rows.filter((row) => !row.outOfScope);
  const outOfScope = rows.filter((row) => row.outOfScope);

  return [
    frontmatter({ id: "backlog-index", type: "index", title: "Backlog", created_by: "sync", tags: ["adoa", "moc"] }),
    "# Backlog",
    "Generated by adoa. Read only: edit only `## Notes` sections.",
    "## Sprints",
    region("sprints", renderSprints(sprintPaths)),
    "## PBIs by pipeline status",
    region("pbis", renderByStatus(inScope)),
    "## Out of scope",
    region("out-of-scope", renderTable(outOfScope)),
    notesSection,
  ].join("\n\n");
}

function renderSprints(paths: string[]): string {
  return paths.map((path) => `- [[${sprintNoteName(path)}]]`).join("\n") || "None.";
}

function renderByStatus(rows: IndexRow[]): string {
  const statuses = [...new Set(rows.map((row) => row.pipelineStatus))];
  const sections = statuses.map((status) =>
    `### ${status}\n\n${renderTable(rows.filter((row) => row.pipelineStatus === status))}`,
  );

  return sections.join("\n\n") || "None.";
}

function renderTable(rows: IndexRow[]): string {
  if (rows.length === 0) {
    return "None.";
  }

  const lines = rows.map((row) =>
    `| [[${pbiNoteName(row.adoId)}]] | ${escapeCell(row.title)} | ${row.adoState} | ${escapeCell(row.iterationPath ?? "–")} |`,
  );

  return ["| PBI | Title | ADO state | Iteration |", "|---|---|---|---|", ...lines].join("\n");
}
